# Run from repository root. All numerical transformations and plot data use R.
library(ggplot2)
library(jsonlite)
out <- 'Submission_Pack/figures'
dir.create(out, recursive=TRUE, showWarnings=FALSE)
f <- subset(read.csv('Peer_Misleading_Study/reports/main_r/tables.csv'),provider=='pooled')
e <- subset(read.csv('Peer_Misleading_Study/reports/interaction_posthoc/effects.csv'),variant=='primary' & provider=='pooled' & metric=='error')
t <- subset(read.csv('Peer_Misleading_Study/reports/interaction_posthoc/transitions.csv'),comparison=='C3_vs_C2' & provider=='pooled' & baseline_stratum=='all')
m <- subset(read.csv('Math_Supplement/reports/supplementary/tables.csv'),scope=='pooled')
review <- fromJSON('Peer_Misleading_Study/reports/interaction_posthoc/review_audit.json')
pal <- c(Correct='#147E77',Wrong='#C45F48',Abstain='#8B9BAE')
theme_set(theme_minimal(base_size=13,base_family='Arial') + theme(panel.grid.minor=element_blank(),plot.title=element_text(face='bold',color='#142C40'),legend.position='bottom',plot.margin=margin(12,18,12,12)))
saveplot <- function(name,p,w=10,h=4.8) ggsave(file.path(out,paste0(name,'.png')),p,width=w,height=h,dpi=200,bg='white')
cond <- c('baseline','C0','C1','C2','C3','C4','C5')
lab <- c('Initial answer','C0  Neutral recheck','C1  Wrong answer','C2  Wrong + reason','C3  Structured / wrong','C4  Correct + reason','C5  Structured / correct')
long <- do.call(rbind,lapply(seq_along(pal),function(i)data.frame(condition=f$condition,outcome=names(pal)[i],n=f[[c('correct','incorrect','abstain')[i]]],den=f$n)))
long$pct <- 100*long$n/long$den
long$condition <- factor(long$condition,levels=rev(cond),labels=rev(lab))
long$outcome <- factor(long$outcome,levels=names(pal))
p <- ggplot(long,aes(pct,condition,fill=outcome))+geom_col(position=position_stack(reverse=TRUE),width=.67)+geom_text(aes(label=sprintf('%.1f%%',pct)),position=position_stack(vjust=.5,reverse=TRUE),color='white',size=3.8)+scale_fill_manual(values=pal)+scale_x_continuous(limits=c(0,100),breaks=seq(0,100,25),labels=function(x)paste0(x,'%'))+labs(title='Correct, wrong and abstaining outputs',subtitle='719 complete units in each parallel condition',x=NULL,y=NULL,fill=NULL)+theme(panel.grid.major.y=element_blank())
saveplot('outcome_composition',p)
elab <- c('C0 vs Initial: neutral recheck','C1 vs C0: wrong answer','C2 vs C0: wrong + reason','C3 vs C2: structured / wrong','C5 vs C4: structured / correct')
e <- e[match(c('C0_vs_baseline','C1_vs_C0','C2_vs_C0','C3_vs_C2','C5_vs_C4'),e$comparison),]
e$label <- elab; e$y <- 5:1
e$display <- sprintf('%+.2f [%+.2f, %+.2f]',e$difference_pp,e$ci_low_pp,e$ci_high_pp)
p <- ggplot(e,aes(difference_pp,factor(label,levels=rev(elab))))+geom_vline(xintercept=0,color='#8B9BAE',linetype='dashed')+geom_segment(aes(x=ci_low_pp,xend=ci_high_pp,yend=factor(label,levels=rev(elab))),linewidth=.9,color='#142C40')+geom_point(size=3.3,color='#147E77')+scale_x_continuous(limits=c(-25,25),breaks=seq(-20,20,10))+labs(title='Differences in error rate, with uncertainty',subtitle='Post hoc: point estimates and 95% question-cluster bootstrap intervals',x='Percentage-point difference (first condition minus second)',y=NULL,caption='Left of zero: less error. Right of zero: more error. 719 paired units; 120 question clusters.\nPointwise exploratory intervals; not adjusted for multiple comparisons.')+theme(panel.grid.major.y=element_blank(),plot.caption=element_text(hjust=0))
saveplot('error_effects',p,h=4.5)
rates <- data.frame(condition=f$condition,wrong=f$incorrect,correct=f$correct,abstain=f$abstain,n=f$n,rate=f$incorrect/f$n)
stopifnot(all(rates$wrong+rates$correct+rates$abstain==rates$n),all(rates$n==719))
bar_data <- rbind(
 transform(rates[match(c('C0','C1','C2'),rates$condition),],panel='1. Misleading input',label=c('C0\nNeutral recheck','C1\nWrong answer','C2\nWrong + reason')),
 transform(rates[match(c('C2','C3'),rates$condition),],panel='2. Structured double-check',label=c('C2\nOrdinary recheck','C3\nStructured check')))
bar_data$label <- factor(bar_data$label,levels=unique(bar_data$label))
p <- ggplot(bar_data,aes(label,rate,fill=condition))+geom_col(width=.6)+geom_text(aes(label=sprintf('%.2f%%',100*rate)),vjust=-.55,size=5,fontface='bold')+facet_wrap(~panel,scales='free_x',nrow=1)+scale_fill_manual(values=c(C0='#8B9BAE',C1='#C45F48',C2='#C45F48',C3='#147E77'),guide='none')+scale_y_continuous(limits=c(0,1),breaks=seq(0,1,.25),labels=function(x)paste0(100*x,'%'),expand=expansion(mult=c(0,.01)))+labs(title='Error rates under different prompts',subtitle='Wrong answers / all 719 responses per condition',x=NULL,y='Error rate',caption='Correct answers and abstentions are not counted as errors; both remain in the denominator.\nPost-hoc comparisons of parallel conditions. No time sequence or continuous curve.')+theme(panel.grid.major.x=element_blank(),strip.text=element_text(face='bold',size=14),axis.text.x=element_text(size=11),plot.caption=element_text(hjust=0))
saveplot('error_rate_comparisons',p,w=11,h=5)
write.csv(bar_data,'Submission_Pack/evidence/plotted_error_rates.csv',row.names=FALSE)
states <- c('correct','incorrect','abstain'); labels <- c('Correct','Wrong','Abstain')
t$from <- factor(t$from,levels=rev(states),labels=rev(labels));t$to <- factor(t$to,levels=states,labels=labels)
p <- ggplot(t,aes(to,from,fill=n))+geom_tile(color='white',linewidth=1.5)+geom_text(aes(label=n,color=n>180),size=6,fontface='bold')+scale_fill_gradient(low='#F0F4F7',high='#147E77',limits=c(0,228),breaks=c(0,114,228))+scale_color_manual(values=c('FALSE'='#142C40','TRUE'='white'),guide='none')+coord_fixed()+labs(title='Where do the same units land in C2 and C3?',subtitle='All 719 paired units; cell color represents the count',x='C3: structured checking',y='C2: wrong advice + neutral recheck',fill='Pairs',caption='Parallel branches, not chronological steps. All nine cells are retained.')+theme(panel.grid=element_blank(),legend.position='right',plot.caption=element_text(hjust=0))
saveplot('paired_outcomes',p,w=8.6,h=4.7)
rv <- data.frame(label=c('Clearly withholds a date','Unconfirmed candidate only','Challenges the premise','Retains a date assertion'),n=as.integer(unlist(review$withdrawal_labels[c('withholds','qualified_candidate','premise_challenge','mixed_assertion')])))
stopifnot(sum(rv$n)==144,sum(t$n)==719)
p <- ggplot(rv,aes(n,factor(label,levels=rev(label))))+geom_col(fill='#147E77',width=.6)+geom_text(aes(label=n),hjust=-.3,size=4.5)+scale_x_continuous(limits=c(0,125),breaks=c(0,40,80,120))+labs(title='What did the 144 wrong-to-abstain pairs say?',x='Number of pairs',y=NULL,caption='Targeted, unblinded AI review. Other background claims may remain unchecked.')+theme(panel.grid.major.y=element_blank(),plot.caption=element_text(hjust=0))
saveplot('withdrawal_review',p,h=3.5)
m <- m[match(cond,m$condition),]
p <- ggplot(m,aes(correct,factor(condition,levels=rev(cond),labels=rev(lab))))+geom_point(size=3.2,color='#147E77')+geom_text(aes(label=paste0(correct,' / ',n)),hjust=-.25,size=3.7)+scale_x_continuous(limits=c(0,80),breaks=c(0,20,40,60,71))+labs(title='Mathematics: correct final conclusions',subtitle='13 selected items; 71 complete units per condition',x='Number correct (maximum possible: 71)',y=NULL,caption='Descriptive counts only. No population interval or universal ranking.')+geom_vline(xintercept=71,color='#8B9BAE',linetype='dashed')+theme(panel.grid.major.y=element_blank(),plot.caption=element_text(hjust=0))
saveplot('math_counts',p,h=4.4)
mx <- xtabs(n~from+to,t)[labels,labels]
ramp <- colorRampPalette(c('#F0F4F7','#147E77'))(229)
heat <- lapply(1:3,function(i)unname(ramp[as.integer(mx[i,])+1]))
data <- list(error_rates=unname(lapply(seq_len(nrow(rates)),function(i)as.list(rates[i,]))),effects=unname(lapply(seq_len(nrow(e)),function(i)as.list(e[i,]))),heat_colors=heat,review=unname(lapply(seq_len(nrow(rv)),function(i)as.list(rv[i,]))),composition=unname(lapply(seq_len(nrow(f)),function(i)list(condition=f$condition[i],correct=100*f$correct[i]/f$n[i],incorrect=100*f$incorrect[i]/f$n[i],abstain=100*f$abstain[i]/f$n[i]))))
write_json(data,'Submission_Pack/evidence/visualization_data.json',auto_unbox=TRUE,pretty=TRUE,digits=NA)
write.csv(e,'Submission_Pack/evidence/plotted_effects.csv',row.names=FALSE)
write.csv(long,'Submission_Pack/evidence/plotted_composition.csv',row.names=FALSE)
cat('R figures and editable-slide chart data exported.\n')
